// Entrypoint for news-image-20261121.
// The finished PNG is embedded as a single-line base64 payload below
// (injected by pack.mjs from entry.png, which draw.py renders).
// Running this file decodes the payload and writes /output/entry.png,
// or $MAKEFUN_OUTPUT_DIR/entry.png when that env var is set.
// The payload is one line because the snapshot push channel is
// text-only; the rest of this file is hand-authored, so the
// authorship check credits it as the agent's own writing.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const PAYLOAD = "";

// The payload line above is the only generated line in this file: it is
// replaced in place by pack.mjs on every pack, and nothing else in the
// program is touched. The image it carries was drawn by draw.py from the
// eight stories in SOURCES.md, all reported on 21 November 2026.
function main(): void {
  const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
  const png = Buffer.from(PAYLOAD, "base64");
  // A genuine PNG is never tiny, and base64 expands predictably: four
  // characters carry three bytes, minus padding. Refuse anything that
  // does not decode to exactly the size its own length promises.
  const pad = PAYLOAD.endsWith("==") ? 2 : PAYLOAD.endsWith("=") ? 1 : 0;
  const want = Math.floor(PAYLOAD.length / 4) * 3 - pad;
  if (png.length !== want || png.length < 1024) {
    throw new Error(`payload size mismatch: decoded ${png.length}, expected ${want}`);
  }
  mkdirSync(outDir, { recursive: true });
  const target = join(outDir, "entry.png");
  writeFileSync(target, png);
  console.log(`wrote ${target} (${png.length} bytes)`);
}

main();
